<template><PageContainer><PageHeader eyebrow="SCR-MON-007" title="Diagnostics" description="Analyse structuree des incidents et recommandations techniques."><template #actions><RouterLink class="mon-pill" to="/app/monitoring"><ArrowLeft/>Retour</RouterLink><button class="mon-btn mon-btn--primary" @click="store.chargerDiagnostics"><RefreshCw/>Actualiser</button></template></PageHeader><SectionBlock v-if="canGenerate" title="Generer un diagnostic" description="Generation ciblee sur un incident, sans JSON libre."><form class="mon-grid" @submit.prevent="generate"><label class="mon-field"><span>Incident ID</span><input v-model="incidentId" maxlength="160"/></label><label class="mon-field"><span>Trace IDs (separes par virgule)</span><input v-model="traceIds" placeholder="trace-1, trace-2"/></label><div class="mon-actions mon-field--full"><button class="mon-btn mon-btn--primary" type="submit">Generer</button></div></form></SectionBlock><LoadingState v-if="store.state.status==='loading'" title="Diagnostics en cours" message="Lecture ou generation du diagnostic."/><ErrorState v-else-if="store.state.status==='error'" title="Diagnostics indisponibles" :message="store.state.errorMessage??'Erreur technique.'"/><SectionBlock v-else title="Historique diagnostics" description="Causes probables et recommandations issues du domaine Monitoring."><MonitoringEmptyState v-if="!store.state.diagnostics.length" title="Aucun diagnostic" message="Aucun diagnostic n'a encore ete produit."/><div v-else class="mon-stack"><article v-for="d in store.state.diagnostics" :key="`${d.incidentId}-${d.genereLe}`" class="mon-panel"><div class="mon-toolbar"><div><strong>{{d.incidentId}}</strong><div class="mon-muted">{{d.resume}}</div></div><MonitoringStatusBadge :level="d.niveau"/></div><div class="mon-grid"><div><h3>Causes probables</h3><ul class="mon-list"><li v-for="c in d.causesProbables" :key="c">{{c}}</li></ul></div><div><h3>Recommandations</h3><ul class="mon-list"><li v-for="r in d.recommandations" :key="r">{{r}}</li></ul></div></div></article></div></SectionBlock></PageContainer></template>
<script setup lang="ts">import {ref} from 'vue';import {RouterLink} from 'vue-router';import {ArrowLeft,RefreshCw} from 'lucide-vue-next';import PageContainer from '../../../shared/layout/PageContainer.vue';import PageHeader from '../../../shared/layout/PageHeader.vue';import SectionBlock from '../../../shared/layout/SectionBlock.vue';import LoadingState from '../../../shared/ui/LoadingState.vue';import ErrorState from '../../../shared/ui/ErrorState.vue';import MonitoringEmptyState from '../components/MonitoringEmptyState.vue';import MonitoringStatusBadge from '../components/MonitoringStatusBadge.vue';import {hasMonitoringPermission} from '../access/monitoring-access';import {required} from '../validation/monitoring-form.validation';import {useMonitoringStore} from '../stores/monitoring.store';import '../monitoring.css';const store=useMonitoringStore(),incidentId=ref(''),traceIds=ref('');const canGenerate=hasMonitoringPermission('monitoring.diagnostics.create');async function generate(){if(required(incidentId.value,'Incident ID'))return;const ids=traceIds.value.split(',').map(x=>x.trim()).filter(Boolean);await store.genererDiagnostic(incidentId.value.trim(),ids.length?{traceIds:ids}:{})}</script>
